import{_ as s,o as t,c as n,a2 as o}from"./chunks/framework.BXzK3EA4.js";const c=JSON.parse('{"title":"My Abuse","description":"","frontmatter":{"title":"My Abuse"},"headers":[],"relativePath":"operations-knowledge-base/presales-support/my-abuse.md","filePath":"operations-knowledge-base/presales-support/my-abuse.md","lastUpdated":1794292919000}'),a={name:"operations-knowledge-base/presales-support/my-abuse.md"};function r(i,e,p,u,l,d){return t(),n("div",null,[...e[0]||(e[0]=[o('<h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>This document explains how to view IP addresses that have been suspended due to abuse complaints, understand the reason for the suspension, and apply for unsuspension after resolving the reported issue.</p><p><strong>Supported Products:</strong></p><ul><li>VPS (Virtual Private Server)</li><li>Bare Metal Cloud</li><li>Dedicated Servers</li></ul><hr><h2 id="_1-feature-overview" tabindex="-1">1. Feature Overview <a class="header-anchor" href="#_1-feature-overview" aria-label="Permalink to &quot;1. Feature Overview&quot;">​</a></h2><p>The <strong>Abuse Suspension</strong> page allows customers to view IP addresses that have been suspended due to abuse reports or policy violations.</p><p>Customers can review the suspended IP information, understand the reason for the suspension, complete the required corrective actions, and submit a support ticket to request unsuspension.</p><hr><h2 id="_2-accessing-the-abuse-suspension-page" tabindex="-1">2. Accessing the Abuse Suspension Page <a class="header-anchor" href="#_2-accessing-the-abuse-suspension-page" aria-label="Permalink to &quot;2. Accessing the Abuse Suspension Page&quot;">​</a></h2><p>Log in to the <strong>Raksmart Client Portal</strong>, then navigate to:</p><p><strong>Client Center → Technical Support → Abuse Suspension</strong></p><p>This will open the <strong>My Suspension List</strong> page.</p><hr><h2 id="_3-viewing-suspension-information" tabindex="-1">3. Viewing Suspension Information <a class="header-anchor" href="#_3-viewing-suspension-information" aria-label="Permalink to &quot;3. Viewing Suspension Information&quot;">​</a></h2><p>The <strong>My Suspension List</strong> page displays information for IP addresses that have been suspended.</p><p>The following information is available:</p><ul><li><strong>Suspended IP</strong> – The IP address that has been suspended.</li><li><strong>Reason</strong> – The reason for the suspension (for example: <strong>Blocked due to Abuse</strong>).</li><li><strong>Suspended Time</strong> – The date and time when the IP was suspended.</li><li><strong>Status</strong> – The current status of the IP (for example: <strong>Blocked</strong>).</li></ul><hr><h2 id="_4-how-to-request-unsuspension" tabindex="-1">4. How to Request Unsuspension <a class="header-anchor" href="#_4-how-to-request-unsuspension" aria-label="Permalink to &quot;4. How to Request Unsuspension&quot;">​</a></h2><p>If your IP has been suspended, please follow these steps:</p><ol><li><p>Review the suspension information and understand the reason for the abuse complaint.</p></li><li><p>Resolve the reported issue by removing or correcting the abusive or non-compliant content or service.</p></li><li><p>Submit a support ticket through the <strong>Technical Support</strong> section.</p></li><li><p>In your ticket, provide:</p><ul><li>The suspended IP address.</li><li>A description of the issue.</li><li>Details of the corrective actions you have taken.</li></ul></li><li><p>Our technical team will review your request and determine whether the IP can be restored.</p></li></ol><hr><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><p>⚠️ Simply requesting unsuspension without resolving the reported issue may result in the request being rejected.</p><p>⚠️ Please ensure that all reported content or services have been fully corrected before submitting an unsuspension request.</p><p>⚠️ Repeated abuse violations may result in additional penalties or permanent suspension in accordance with the applicable service policies.</p><hr>',28)])])}const g=s(a,[["render",r]]);export{c as __pageData,g as default};
